# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: turn what a person types (a tag, a start.gg player id, a start.gg profile url) into
# one start.gg player. start.gg's API has no search by tag, so tags go through supermajor.gg's
# search (ds.data.raw.supermajor.search_players); its `S<digits>` ids are start.gg player ids.
# Usage: `lookup = asyncio.run(resolve_player("Sparg0"))`; `asyncio.run(find_players("luke"))`.
# ---------------------------------------------------------------------------
from __future__ import annotations

import asyncio
import re
from typing import Literal

import httpx2
from pydantic import BaseModel, Field

from ds.data.raw import startgg
from ds.data.raw.supermajor import PlayerMatch, pick_player, search_players

__all__ = ["PlayerCandidate", "PlayerLookup", "PlayerLookupError", "find_players", "resolve_player"]

_PLAYER_ID_RE = re.compile(r"^S?(\d+)$")
MatchType = Literal["player_id", "profile", "tag_exact", "tag_any_case"]


class PlayerLookupError(ValueError):
    """No player could be worked out from the input; the message says what to give instead"""


class PlayerCandidate(BaseModel):
    """One player from a tag search"""

    player_id: int = Field(description="start.gg player id, eg 158026; pass it as `player` to pick this one")
    tag: str
    country: str | None = None
    state: str | None = None
    num_events: int = Field(0, description="Events attended (activity); search results are sorted by this")


class PlayerLookup(BaseModel):
    """Which player an input was resolved to, and how"""

    query: str = Field(description="The input as given: tag, player id or profile url")
    match_type: MatchType = Field(
        description="player_id / profile: used as given; tag_exact: same-case tag; tag_any_case: matched ignoring case"
    )
    player_id: int = Field(description="start.gg player id")
    tag: str
    prefix: str | None = Field(None, description="Sponsor / team prefix, eg 'FaZe'")
    country: str | None = Field(None, description="Tag lookups only")
    state: str | None = Field(None, description="Tag lookups only")
    num_events: int | None = Field(None, description="Events attended (tag lookups only)")
    tied_matches: int = Field(1, description="Players sharing the tag at the same level; >1: most events won")


def _candidate(match: PlayerMatch) -> PlayerCandidate | None:
    found = _PLAYER_ID_RE.match(match.player_id)
    if not found:
        return None
    return PlayerCandidate(
        player_id=int(found.group(1)),
        tag=match.tag,
        country=match.country,
        state=match.state,
        num_events=match.num_events,
    )


async def _search(tag: str) -> list[PlayerMatch]:
    try:
        return await asyncio.to_thread(search_players, tag)
    except (httpx2.HTTPError, ValueError) as e:
        raise PlayerLookupError(
            " ".join(
                [
                    f"tag search is not available ({e});",
                    "give the player's start.gg profile url (start.gg/user/...) or player id instead",
                ]
            )
        ) from e


async def find_players(tag: str) -> list[PlayerCandidate]:
    """Players whose tag contains `tag` (any case), most events first

    Args:
        tag: a tag or part of one, eg 'luke'.
    """
    return [c for match in await _search(tag) if (c := _candidate(match))]


async def resolve_player(player: str) -> PlayerLookup:
    """The start.gg player for a tag, a player id or a profile url

    Tags aren't unique: an exact-case match wins, then any case, and among equals the player
    with the most events (`tied_matches` says how many there were). Raises PlayerLookupError
    when nobody matches or the tag search is down.

    Args:
        player: a tag ('Sparg0'), a start.gg player id ('158026'; supermajor's 'S158026' works
            too), or a start.gg profile url / slug ('https://www.start.gg/user/b5230de8').
    """
    player = player.strip()
    if found := _PLAYER_ID_RE.match(player):
        try:
            who = await startgg.player(int(found.group(1)))
        except ValueError as e:
            raise PlayerLookupError(str(e)) from e
        return PlayerLookup(query=player, match_type="player_id", player_id=who.id, tag=who.tag, prefix=who.prefix)
    if "user/" in player or "start.gg" in player:
        try:
            who = await startgg.user_player(player)
        except ValueError as e:
            raise PlayerLookupError(str(e)) from e
        return PlayerLookup(query=player, match_type="profile", player_id=who.id, tag=who.tag, prefix=who.prefix)
    try:
        picked = pick_player(player, await _search(player))
    except PlayerLookupError:
        raise
    except ValueError as e:  # nobody has this tag; the message lists similar tags
        raise PlayerLookupError(str(e).replace("supermajor.gg player", "player")) from e
    match = picked.player
    candidate = _candidate(match) if match else None
    if candidate is None:
        raise PlayerLookupError(f"{player!r} was found but has no start.gg player id; give a profile url instead")
    return PlayerLookup(
        query=player,
        match_type=picked.match_type,
        player_id=candidate.player_id,
        tag=candidate.tag,
        country=candidate.country,
        state=candidate.state,
        num_events=candidate.num_events,
        tied_matches=picked.tied_matches,
    )
